/** Source: starter_choose.c → Task_HandleStarterChooseInput */
export const Task_HandleStarterChooseInput: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let selection = task.data[0];

      if (JOY_NEW(A_BUTTON))
      {
          let spriteId = 0;

          ClearStarterLabel();

           
          spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_StarterCircle',  sPokeballCoords[selection][0], sPokeballCoords[selection][1], 1);
          task.data[2] = spriteId;

           
          spriteId = CreatePokemonFrontSprite(GetStarterPokemon(task.data[0]), sPokeballCoords[selection][0], sPokeballCoords[selection][1]);
          _gs(rt, spriteId).affineAnims = sAffineAnims_StarterPokemon;
          rt.setSpriteCallback(spriteId, SpriteCB_StarterPokemon);

          task.data[1] = spriteId;
          task.func = (t) => Task_WaitForStarterSprite(t, rt);
      }
      else if (JOY_NEW(DPAD_LEFT) && selection > 0)
      {
          task.data[0]--;
          task.func = (t) => Task_MoveStarterChooseCursor(t, rt);
      }
      else if (JOY_NEW(DPAD_RIGHT) && selection < STARTER_MON_COUNT - 1)
      {
          task.data[0]++;
          task.func = (t) => Task_MoveStarterChooseCursor(t, rt);
      }
};

